theorem LeanProofs.exists_prime_ge : ∀ (n : ℕ), ∃ p, n ≤ p ∧ Nat.Prime p :=
fun n =>
  have hpos := Nat.factorial_pos n;
  have hne := fun a => LeanProofs.exists_prime_ge._proof_1_1 n hpos a;
  let p := (n.factorial + 1).minFac;
  have hp := Nat.minFac_prime hne;
  Exists.intro p
    ⟨Decidable.byContradiction fun hlt =>
        have h1 :=
          Nat.dvd_factorial (Nat.Prime.pos hp) (LT.lt.le (Eq.mp (congrArg (fun _a => _a) (propext not_le)) hlt));
        have h2 := Nat.minFac_dvd (n.factorial + 1);
        have h3 := (Nat.dvd_add_right h1).mp h2;
        LT.lt.ne' (Nat.Prime.one_lt hp) (Nat.dvd_one.mp h3),
      hp⟩
